import * as React from 'react';
import * as PopoverPrimitive from '@radix-ui/react-popover';

function classes(...values: Array<string | undefined | false>) {
  return values.filter(Boolean).join(' ');
}

export const EditorPopover = PopoverPrimitive.Root;
export const EditorPopoverTrigger = PopoverPrimitive.Trigger;

export interface EditorPopoverContentProps
  extends React.ComponentPropsWithoutRef<typeof PopoverPrimitive.Content> {
  container?: HTMLElement | null;
}

export const EditorPopoverContent = React.forwardRef<
  React.ElementRef<typeof PopoverPrimitive.Content>,
  EditorPopoverContentProps
>(({ className, container, sideOffset = 4, ...props }, ref) => (
  <PopoverPrimitive.Portal container={container}>
    <PopoverPrimitive.Content
      ref={ref}
      sideOffset={sideOffset}
      className={classes(
        'bgrid-shadcn-popover z-50 rounded-md border bg-popover p-3 text-popover-foreground shadow-md outline-none',
        className,
      )}
      {...props}
    />
  </PopoverPrimitive.Portal>
));

EditorPopoverContent.displayName = 'EditorPopoverContent';

import * as React from 'react';
import type { BGridPluginEditorConfig } from 'beautiful-grid';

export interface BaseOptions {
  id: string;
  ariaLabel: string;
  placeholder?: string;
}

export function defineEditorPlugin<T>(
  config: Omit<BGridPluginEditorConfig<T>, 'type'>,
): BGridPluginEditorConfig<T> {
  return { ...config, type: 'plugin' };
}

export function useEditorLifecycle(cancel: () => void) {
  const [open, setOpen] = React.useState(true);
  const committedRef = React.useRef(false);
  return {
    open,
    commitStarted: () => {
      committedRef.current = true;
    },
    onOpenChange: (nextOpen: boolean) => {
      setOpen(nextOpen);
      if (!nextOpen && !committedRef.current) cancel();
    },
  };
}

export function EditorTrigger({
  ariaLabel,
  children,
  icon,
  cancel,
}: {
  ariaLabel: string;
  children: React.ReactNode;
  icon?: React.ReactNode;
  cancel: () => void;
}) {
  return (
    <button
      type='button'
      className='bgrid-shadcn-trigger'
      aria-label={ariaLabel}
      autoFocus
      onKeyDown={event => {
        if (event.key === 'Escape' || event.key === 'Esc') {
          event.preventDefault();
          event.stopPropagation();
          cancel();
        }
      }}
    >
      <span className='bgrid-shadcn-trigger-label'>{children}</span>
      {icon ? <span className='bgrid-shadcn-trigger-icon'>{icon}</span> : null}
    </button>
  );
}

import * as React from 'react';
import type { BGridEditorPluginProps, BGridPluginEditorConfig } from 'beautiful-grid';
import { Check, ChevronDown } from 'lucide-react';
import { EditorPopover, EditorPopoverContent, EditorPopoverTrigger } from './editor-popover';
import { defineEditorPlugin, EditorTrigger, type BaseOptions, useEditorLifecycle } from './shared';

export interface ShadcnSelectEditorOption<Value extends string | number> {
  value: Value;
  label: React.ReactNode;
  disabled?: boolean;
}

export interface ShadcnSelectEditorPluginOptions<Value extends string | number> extends BaseOptions {
  options: ShadcnSelectEditorOption<Value>[];
}

export function createShadcnSelectEditorPlugin<T, Value extends string | number = string>(
  options: ShadcnSelectEditorPluginOptions<Value>,
): BGridPluginEditorConfig<T> {
  function Editor({ value, column, commit, cancel, getPortalContainer }: BGridEditorPluginProps<T>) {
    const lifecycle = useEditorLifecycle(cancel);
    const selected = options.options.find(option => option.value === value);
    return (
      <EditorPopover open={lifecycle.open} onOpenChange={lifecycle.onOpenChange}>
        <EditorPopoverTrigger asChild>
          <EditorTrigger ariaLabel={options.ariaLabel} cancel={cancel} icon={<ChevronDown />}>
            {selected?.label ?? options.placeholder ?? String(value ?? '')}
          </EditorTrigger>
        </EditorPopoverTrigger>
        <EditorPopoverContent container={getPortalContainer()} className='w-64 p-1' align='start'>
          <div role='listbox' aria-label={options.ariaLabel} className='bgrid-shadcn-list'>
            {options.options.map(option => (
              <button
                key={String(option.value)}
                type='button'
                role='option'
                aria-selected={option.value === value}
                disabled={option.disabled}
                className='bgrid-shadcn-option'
                onClick={() => {
                  lifecycle.commitStarted();
                  void commit([{ key: column.key, value: option.value }]);
                }}
              >
                <span>{option.label}</span>
                {option.value === value ? <Check aria-hidden='true' /> : null}
              </button>
            ))}
          </div>
        </EditorPopoverContent>
      </EditorPopover>
    );
  }
  Editor.displayName = `ShadcnSelectEditor(${options.id})`;
  return defineEditorPlugin<T>({ id: options.id, component: Editor });
}

import * as React from 'react';
import type { BGridEditorPluginProps, BGridPluginEditorConfig } from 'beautiful-grid';
import { CalendarDays, ChevronLeft, ChevronRight } from 'lucide-react';
import { EditorPopover, EditorPopoverContent, EditorPopoverTrigger } from './editor-popover';
import { defineEditorPlugin, EditorTrigger, type BaseOptions, useEditorLifecycle } from './shared';

function formatDate(date: Date) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
}

function parseDate(value: unknown) {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return undefined;
  const [year, month, day] = value.split('-').map(Number);
  const date = new Date(year!, month! - 1, day);
  return formatDate(date) === value ? date : undefined;
}

export interface ShadcnDatePickerEditorPluginOptions extends BaseOptions {
  min?: string;
  max?: string;
  weekStartsOn?: 0 | 1;
}

export function createShadcnDatePickerEditorPlugin<T>(
  options: ShadcnDatePickerEditorPluginOptions,
): BGridPluginEditorConfig<T> {
  function Editor({ value, column, commit, cancel, getPortalContainer }: BGridEditorPluginProps<T>) {
    const lifecycle = useEditorLifecycle(cancel);
    const selectedDate = parseDate(value);
    const [month, setMonth] = React.useState(() => {
      const initial = selectedDate ?? new Date();
      return new Date(initial.getFullYear(), initial.getMonth(), 1);
    });
    const days = React.useMemo(() => {
      const result: Date[] = [];
      const first = new Date(month.getFullYear(), month.getMonth(), 1);
      const offset = (first.getDay() - (options.weekStartsOn ?? 0) + 7) % 7;
      const start = new Date(first.getFullYear(), first.getMonth(), 1 - offset);
      for (let index = 0; index < 42; index += 1) {
        result.push(new Date(start.getFullYear(), start.getMonth(), start.getDate() + index));
      }
      return result;
    }, [month]);
    const weekdayLabels = options.weekStartsOn === 1
      ? ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
      : ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

    return (
      <EditorPopover open={lifecycle.open} onOpenChange={lifecycle.onOpenChange}>
        <EditorPopoverTrigger asChild>
          <EditorTrigger ariaLabel={options.ariaLabel} cancel={cancel} icon={<CalendarDays />}>
            {typeof value === 'string' && value ? value : options.placeholder ?? 'Select date'}
          </EditorTrigger>
        </EditorPopoverTrigger>
        <EditorPopoverContent container={getPortalContainer()} className='w-auto' align='start'>
          <div className='bgrid-shadcn-calendar-header'>
            <strong>{month.toLocaleDateString(undefined, { month: 'long', year: 'numeric' })}</strong>
            <div>
              <button type='button' aria-label='Previous month' onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() - 1, 1))}><ChevronLeft /></button>
              <button type='button' aria-label='Next month' onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() + 1, 1))}><ChevronRight /></button>
            </div>
          </div>
          <div className='bgrid-shadcn-calendar-grid bgrid-shadcn-weekdays'>
            {weekdayLabels.map(label => <span key={label}>{label}</span>)}
          </div>
          <div className='bgrid-shadcn-calendar-grid'>
            {days.map(date => {
              const dateValue = formatDate(date);
              const disabled = Boolean((options.min && dateValue < options.min) || (options.max && dateValue > options.max));
              return (
                <button
                  key={dateValue}
                  type='button'
                  disabled={disabled}
                  data-outside={date.getMonth() !== month.getMonth() || undefined}
                  data-selected={dateValue === value || undefined}
                  onClick={() => {
                    lifecycle.commitStarted();
                    void commit([{ key: column.key, value: dateValue }]);
                  }}
                >
                  {date.getDate()}
                </button>
              );
            })}
          </div>
        </EditorPopoverContent>
      </EditorPopover>
    );
  }
  Editor.displayName = `ShadcnDatePickerEditor(${options.id})`;
  return defineEditorPlugin<T>({ id: options.id, component: Editor });
}

import * as React from 'react';
import type { BGridEditorPluginProps, BGridPluginEditorConfig } from 'beautiful-grid';
import { Check } from 'lucide-react';
import { EditorPopover, EditorPopoverContent, EditorPopoverTrigger } from './editor-popover';
import { defineEditorPlugin, EditorTrigger, type BaseOptions, useEditorLifecycle } from './shared';

const DEFAULT_COLORS = [
  '#0F172A', '#64748B', '#EF4444', '#F97316', '#F59E0B', '#10B981', '#06B6D4', '#3B82F6',
  '#6366F1', '#8B5CF6', '#D946EF', '#F43F5E', '#1677FF', '#13C2C2', '#52C41A', '#FA8C16',
];

export interface ShadcnColorPickerEditorPluginOptions extends BaseOptions {
  colors?: string[];
  fallbackColor?: string;
}

export function createShadcnColorPickerEditorPlugin<T>(
  options: ShadcnColorPickerEditorPluginOptions,
): BGridPluginEditorConfig<T> {
  const palette = options.colors ?? DEFAULT_COLORS;
  function Editor({ value, column, commit, cancel, getPortalContainer }: BGridEditorPluginProps<T>) {
    const lifecycle = useEditorLifecycle(cancel);
    const initial = typeof value === 'string' && value ? value : options.fallbackColor ?? '#3B82F6';
    const [custom, setCustom] = React.useState(initial);
    const save = (color: string) => {
      const normalized = color.startsWith('#') ? color : `#${color}`;
      if (!/^#[\dA-Fa-f]{3}([\dA-Fa-f]{3})?$/.test(normalized)) return;
      lifecycle.commitStarted();
      void commit([{ key: column.key, value: normalized.toUpperCase() }]);
    };
    return (
      <EditorPopover open={lifecycle.open} onOpenChange={lifecycle.onOpenChange}>
        <EditorPopoverTrigger asChild>
          <EditorTrigger ariaLabel={options.ariaLabel} cancel={cancel}>
            {initial.toUpperCase()} <span className='bgrid-shadcn-color-swatch' style={{ backgroundColor: initial }} />
          </EditorTrigger>
        </EditorPopoverTrigger>
        <EditorPopoverContent container={getPortalContainer()} className='w-64' align='start'>
          <div className='bgrid-shadcn-palette'>
            {palette.map(color => (
              <button key={color} type='button' aria-label={`Color ${color}`} style={{ backgroundColor: color }} onClick={() => save(color)}>
                {initial.toUpperCase() === color.toUpperCase() ? <Check /> : null}
              </button>
            ))}
          </div>
          <form className='bgrid-shadcn-inline-form' onSubmit={event => { event.preventDefault(); save(custom); }}>
            <input aria-label='Custom HEX color' value={custom} onChange={event => setCustom(event.target.value)} placeholder='#000000' />
            <button type='submit'>Apply</button>
          </form>
        </EditorPopoverContent>
      </EditorPopover>
    );
  }
  Editor.displayName = `ShadcnColorPickerEditor(${options.id})`;
  return defineEditorPlugin<T>({ id: options.id, component: Editor });
}

import * as React from 'react';
import type { BGridEditorPluginProps, BGridPluginEditorConfig } from 'beautiful-grid';
import { ChevronDown, ChevronRight } from 'lucide-react';
import { EditorPopover, EditorPopoverContent, EditorPopoverTrigger } from './editor-popover';
import { defineEditorPlugin, EditorTrigger, type BaseOptions, useEditorLifecycle } from './shared';

export interface ShadcnCascaderOption {
  value: string;
  label: React.ReactNode;
  disabled?: boolean;
  children?: ShadcnCascaderOption[];
}

export interface ShadcnCascaderEditorPluginOptions extends BaseOptions {
  options: ShadcnCascaderOption[];
}

export function createShadcnCascaderEditorPlugin<T>(
  options: ShadcnCascaderEditorPluginOptions,
): BGridPluginEditorConfig<T> {
  function Editor({ value, column, commit, cancel, getPortalContainer }: BGridEditorPluginProps<T>) {
    const lifecycle = useEditorLifecycle(cancel);
    const initialPath = Array.isArray(value) ? value.map(String) : [];
    const [path, setPath] = React.useState(initialPath);
    const levels = React.useMemo(() => {
      const result: ShadcnCascaderOption[][] = [options.options];
      let current = options.options;
      for (const segment of path) {
        const match = current.find(option => option.value === segment);
        if (!match?.children?.length) break;
        result.push(match.children);
        current = match.children;
      }
      return result;
    }, [path]);
    return (
      <EditorPopover open={lifecycle.open} onOpenChange={lifecycle.onOpenChange}>
        <EditorPopoverTrigger asChild>
          <EditorTrigger ariaLabel={options.ariaLabel} cancel={cancel} icon={<ChevronDown />}>
            {initialPath.length ? initialPath.join(' / ') : options.placeholder ?? 'Select category'}
          </EditorTrigger>
        </EditorPopoverTrigger>
        <EditorPopoverContent container={getPortalContainer()} className='w-auto p-1' align='start'>
          <div className='bgrid-shadcn-cascader'>
            {levels.map((level, levelIndex) => (
              <div key={levelIndex} className='bgrid-shadcn-list'>
                {level.map(option => (
                  <button
                    key={option.value}
                    type='button'
                    disabled={option.disabled}
                    className='bgrid-shadcn-option'
                    data-selected={path[levelIndex] === option.value || undefined}
                    onClick={() => {
                      const nextPath = [...path.slice(0, levelIndex), option.value];
                      setPath(nextPath);
                      if (!option.children?.length) {
                        lifecycle.commitStarted();
                        void commit([{ key: column.key, value: nextPath }]);
                      }
                    }}
                  >
                    <span>{option.label}</span>{option.children?.length ? <ChevronRight /> : null}
                  </button>
                ))}
              </div>
            ))}
          </div>
        </EditorPopoverContent>
      </EditorPopover>
    );
  }
  Editor.displayName = `ShadcnCascaderEditor(${options.id})`;
  return defineEditorPlugin<T>({ id: options.id, component: Editor });
}

import * as React from 'react';
import type { BGridEditorPluginProps, BGridPluginEditorConfig } from 'beautiful-grid';
import { Clock } from 'lucide-react';
import { EditorPopover, EditorPopoverContent, EditorPopoverTrigger } from './editor-popover';
import { defineEditorPlugin, EditorTrigger, type BaseOptions, useEditorLifecycle } from './shared';

export interface ShadcnTimePickerEditorPluginOptions extends BaseOptions {
  minuteStep?: 1 | 5 | 10 | 15 | 20 | 30;
}

export function createShadcnTimePickerEditorPlugin<T>(
  options: ShadcnTimePickerEditorPluginOptions,
): BGridPluginEditorConfig<T> {
  const step = options.minuteStep ?? 5;
  const hours = Array.from({ length: 24 }, (_, index) => String(index).padStart(2, '0'));
  const minutes = Array.from({ length: 60 / step }, (_, index) => String(index * step).padStart(2, '0'));
  function Editor({ value, column, commit, cancel, getPortalContainer }: BGridEditorPluginProps<T>) {
    const lifecycle = useEditorLifecycle(cancel);
    const [hour, setHour] = React.useState(typeof value === 'string' && /^\d{2}:\d{2}$/.test(value) ? value.slice(0, 2) : '09');
    const [minute, setMinute] = React.useState(typeof value === 'string' && /^\d{2}:\d{2}$/.test(value) ? value.slice(3) : '00');
    return (
      <EditorPopover open={lifecycle.open} onOpenChange={lifecycle.onOpenChange}>
        <EditorPopoverTrigger asChild>
          <EditorTrigger ariaLabel={options.ariaLabel} cancel={cancel} icon={<Clock />}>
            {typeof value === 'string' && value ? value : options.placeholder ?? 'Select time'}
          </EditorTrigger>
        </EditorPopoverTrigger>
        <EditorPopoverContent container={getPortalContainer()} className='w-56' align='start'>
          <div className='bgrid-shadcn-time-columns'>
            <label>Hour<select value={hour} onChange={event => setHour(event.target.value)}>{hours.map(item => <option key={item}>{item}</option>)}</select></label>
            <label>Minute<select value={minute} onChange={event => setMinute(event.target.value)}>{minutes.map(item => <option key={item}>{item}</option>)}</select></label>
          </div>
          <button
            type='button'
            className='bgrid-shadcn-primary-button'
            onClick={() => {
              lifecycle.commitStarted();
              void commit([{ key: column.key, value: `${hour}:${minute}` }]);
            }}
          >
            Apply
          </button>
        </EditorPopoverContent>
      </EditorPopover>
    );
  }
  Editor.displayName = `ShadcnTimePickerEditor(${options.id})`;
  return defineEditorPlugin<T>({ id: options.id, component: Editor });
}

import * as React from 'react';
import type { BGridEditorPluginProps, BGridPluginEditorConfig } from 'beautiful-grid';
import { Check, ChevronDown, Folder, Search } from 'lucide-react';
import { EditorPopover, EditorPopoverContent, EditorPopoverTrigger } from './editor-popover';
import { defineEditorPlugin, EditorTrigger, type BaseOptions, useEditorLifecycle } from './shared';

export interface ShadcnTreeSelectNode {
  value?: string;
  title: React.ReactNode;
  searchText?: string;
  disabled?: boolean;
  children?: ShadcnTreeSelectNode[];
}

export interface ShadcnTreeSelectEditorPluginOptions extends BaseOptions {
  treeData: ShadcnTreeSelectNode[];
}

function filterTree(nodes: ShadcnTreeSelectNode[], query: string): ShadcnTreeSelectNode[] {
  if (!query) return nodes;
  const normalizedQuery = query.toLowerCase();
  return nodes.flatMap(node => {
    const children = node.children ? filterTree(node.children, query) : undefined;
    const searchable = `${node.searchText ?? ''} ${typeof node.title === 'string' ? node.title : ''} ${node.value ?? ''}`.toLowerCase();
    if (!searchable.includes(normalizedQuery) && !children?.length) return [];
    return [{ ...node, ...(children ? { children } : {}) }];
  });
}

export function createShadcnTreeSelectEditorPlugin<T>(
  options: ShadcnTreeSelectEditorPluginOptions,
): BGridPluginEditorConfig<T> {
  function Editor({ value, column, commit, cancel, getPortalContainer }: BGridEditorPluginProps<T>) {
    const lifecycle = useEditorLifecycle(cancel);
    const [query, setQuery] = React.useState('');
    const filteredTree = React.useMemo(() => filterTree(options.treeData, query), [query]);
    const renderNodes = (nodes: ShadcnTreeSelectNode[], depth = 0): React.ReactNode => nodes.map((node, index) => {
      const nodeValue = node.value ?? '';
      return (
        <React.Fragment key={nodeValue || `${depth}-${index}`}>
          <button
            type='button'
            className='bgrid-shadcn-tree-option'
            style={{ paddingInlineStart: `${8 + depth * 18}px` }}
            disabled={!nodeValue || node.disabled}
            data-selected={nodeValue === value || undefined}
            onClick={() => {
              lifecycle.commitStarted();
              void commit([{ key: column.key, value: nodeValue }]);
            }}
          >
            {node.children?.length ? <Folder /> : <span className='bgrid-shadcn-tree-spacer' />}
            <span>{node.title}</span>{nodeValue === value ? <Check /> : null}
          </button>
          {node.children?.length ? renderNodes(node.children, depth + 1) : null}
        </React.Fragment>
      );
    });
    return (
      <EditorPopover open={lifecycle.open} onOpenChange={lifecycle.onOpenChange}>
        <EditorPopoverTrigger asChild>
          <EditorTrigger ariaLabel={options.ariaLabel} cancel={cancel} icon={<ChevronDown />}>
            {typeof value === 'string' && value ? value : options.placeholder ?? 'Select item'}
          </EditorTrigger>
        </EditorPopoverTrigger>
        <EditorPopoverContent container={getPortalContainer()} className='w-72' align='start'>
          <label className='bgrid-shadcn-search'><Search /><input value={query} onChange={event => setQuery(event.target.value)} placeholder='Search…' /></label>
          <div className='bgrid-shadcn-tree'>{renderNodes(filteredTree)}</div>
        </EditorPopoverContent>
      </EditorPopover>
    );
  }
  Editor.displayName = `ShadcnTreeSelectEditor(${options.id})`;
  return defineEditorPlugin<T>({ id: options.id, component: Editor });
}

export function formatCascaderClipboardText(value: unknown): string {
  return Array.isArray(value) && value.every(segment => typeof segment === 'string') ? JSON.stringify(value) : '';
}

export function parseCascaderClipboardText(text: string): string[] {
  const value: unknown = JSON.parse(text);
  if (!Array.isArray(value) || value.length === 0 || !value.every(segment => typeof segment === 'string')) {
    throw new TypeError('Cascader clipboard value must be a non-empty JSON string array.');
  }
  return value;
}

import './beautiful-grid-editors.css';

export * from './createShadcnSelectEditorPlugin';
export * from './createShadcnDatePickerEditorPlugin';
export * from './createShadcnColorPickerEditorPlugin';
export * from './createShadcnCascaderEditorPlugin';
export * from './createShadcnTimePickerEditorPlugin';
export * from './createShadcnTreeSelectEditorPlugin';
export * from './editorUtils';

.bgrid-shadcn-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0 6.5px;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.bgrid-shadcn-trigger-label {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bgrid-shadcn-trigger-icon,
.bgrid-shadcn-option svg,
.bgrid-shadcn-tree-option svg,
.bgrid-shadcn-calendar-header svg,
.bgrid-shadcn-search svg {
  width: 14px;
  height: 14px;
  flex: 0 0 14px;
}

.bgrid-shadcn-popover {
  font-family: var(--bgrid-font-family, inherit);
  font-size: var(--bgrid-font-size, 13px);
}

.bgrid-shadcn-list {
  display: flex;
  min-width: 150px;
  max-height: 240px;
  flex-direction: column;
  gap: 2px;
  overflow-y: auto;
}

.bgrid-shadcn-option,
.bgrid-shadcn-tree-option {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 30px;
  padding: 4px 8px;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
}

.bgrid-shadcn-option:hover,
.bgrid-shadcn-tree-option:hover,
.bgrid-shadcn-option[data-selected],
.bgrid-shadcn-tree-option[data-selected] {
  background: var(--accent, #f1f5f9);
  color: var(--accent-foreground, #0f172a);
}

.bgrid-shadcn-option:disabled,
.bgrid-shadcn-tree-option:disabled,
.bgrid-shadcn-calendar-grid button:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.bgrid-shadcn-calendar-header,
.bgrid-shadcn-calendar-header > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
}

.bgrid-shadcn-calendar-header button,
.bgrid-shadcn-calendar-grid button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: inherit;
  cursor: pointer;
}

.bgrid-shadcn-calendar-header button { width: 28px; height: 28px; }
.bgrid-shadcn-calendar-grid { display: grid; grid-template-columns: repeat(7, 32px); gap: 2px; margin-top: 6px; }
.bgrid-shadcn-calendar-grid button { width: 32px; height: 32px; }
.bgrid-shadcn-calendar-grid button:hover { background: var(--accent, #f1f5f9); }
.bgrid-shadcn-calendar-grid button[data-selected] { background: var(--primary, #2563eb); color: var(--primary-foreground, white); }
.bgrid-shadcn-calendar-grid button[data-outside] { opacity: 0.4; }
.bgrid-shadcn-weekdays { color: var(--muted-foreground, #64748b); text-align: center; font-size: 11px; }

.bgrid-shadcn-color-swatch { width: 14px; height: 14px; border: 1px solid currentColor; border-radius: 3px; }
.bgrid-shadcn-palette { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }
.bgrid-shadcn-palette button { display: flex; height: 32px; align-items: center; justify-content: center; border: 1px solid rgb(0 0 0 / 12%); border-radius: 5px; cursor: pointer; }
.bgrid-shadcn-palette svg { width: 16px; height: 16px; color: white; filter: drop-shadow(0 1px 1px rgb(0 0 0 / 60%)); }
.bgrid-shadcn-inline-form { display: flex; gap: 6px; margin-top: 10px; padding-top: 10px; border-top: 1px solid var(--border, #e2e8f0); }
.bgrid-shadcn-inline-form input,
.bgrid-shadcn-search input,
.bgrid-shadcn-time-columns select { min-width: 0; height: 32px; border: 1px solid var(--input, #cbd5e1); border-radius: 5px; background: var(--background, white); color: inherit; padding: 0 8px; }
.bgrid-shadcn-inline-form button,
.bgrid-shadcn-primary-button { border: 0; border-radius: 5px; background: var(--primary, #2563eb); color: var(--primary-foreground, white); padding: 0 12px; cursor: pointer; }
.bgrid-shadcn-cascader { display: flex; gap: 4px; }
.bgrid-shadcn-cascader > .bgrid-shadcn-list + .bgrid-shadcn-list { border-left: 1px solid var(--border, #e2e8f0); padding-left: 4px; }
.bgrid-shadcn-time-columns { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.bgrid-shadcn-time-columns label { display: flex; flex-direction: column; gap: 4px; color: var(--muted-foreground, #64748b); font-size: 11px; }
.bgrid-shadcn-primary-button { width: 100%; height: 32px; margin-top: 10px; }
.bgrid-shadcn-search { display: flex; align-items: center; gap: 6px; margin-bottom: 8px; }
.bgrid-shadcn-search input { width: 100%; }
.bgrid-shadcn-tree { display: flex; max-height: 260px; flex-direction: column; overflow-y: auto; }
.bgrid-shadcn-tree-option { width: 100%; justify-content: flex-start; }
.bgrid-shadcn-tree-option > svg:last-child { margin-left: auto; }
.bgrid-shadcn-tree-spacer { width: 14px; }
